-- Disposable-database RLS/privilege smoke suite (scripts/run_db_tests.sh).
-- Role switching checks policies/privileges, not actual production login configuration.
-- Generated by scripts/render_db_tests.py: synthetic IDs are valid ULIDs and the
-- version hash is the real RFC 8785 hash of its IR.
BEGIN;
SET LOCAL ROLE twin_owner;
SELECT set_config('app.oidc_issuer','https://test.invalid',true),
       set_config('app.oidc_subject','subject_a',true),
       set_config('app.organization_id','org_01M4YDQK00TA00000000000000',true),
       set_config('app.user_id','usr_01M4YDQK00TA00000000000001',true);
INSERT INTO twin.users(id,oidc_issuer,oidc_subject) VALUES ('usr_01M4YDQK00TA00000000000001','https://test.invalid','subject_a');
INSERT INTO twin.organizations(id,organization_id,name) VALUES ('org_01M4YDQK00TA00000000000000','org_01M4YDQK00TA00000000000000','Tenant A');
INSERT INTO twin.memberships(organization_id,user_id,role) VALUES ('org_01M4YDQK00TA00000000000000','usr_01M4YDQK00TA00000000000001','owner');
INSERT INTO twin.projects(id,organization_id,name,created_by) VALUES ('prj_01M4YDQK00TA00000000000001','org_01M4YDQK00TA00000000000000','Project A','usr_01M4YDQK00TA00000000000001');
SELECT set_config('app.oidc_subject','subject_b',true),
       set_config('app.organization_id','org_01M4YDQK00TB00000000000000',true),
       set_config('app.user_id','usr_01M4YDQK00TB00000000000001',true);
INSERT INTO twin.users(id,oidc_issuer,oidc_subject) VALUES ('usr_01M4YDQK00TB00000000000001','https://test.invalid','subject_b');
INSERT INTO twin.organizations(id,organization_id,name) VALUES ('org_01M4YDQK00TB00000000000000','org_01M4YDQK00TB00000000000000','Tenant B');
INSERT INTO twin.memberships(organization_id,user_id,role) VALUES ('org_01M4YDQK00TB00000000000000','usr_01M4YDQK00TB00000000000001','owner');
INSERT INTO twin.projects(id,organization_id,name,created_by) VALUES ('prj_01M4YDQK00TB00000000000001','org_01M4YDQK00TB00000000000000','Project B','usr_01M4YDQK00TB00000000000001');

SET LOCAL ROLE twin_api;
SELECT set_config('app.oidc_subject','subject_a',true),
       set_config('app.organization_id','org_01M4YDQK00TA00000000000000',true),
       set_config('app.user_id','usr_01M4YDQK00TA00000000000001',true);
DO $$
BEGIN
  IF (SELECT count(*) FROM twin.projects)<>1 THEN RAISE EXCEPTION 'unscoped SELECT leaked projects'; END IF;
  IF EXISTS(SELECT 1 FROM twin.projects WHERE id='prj_01M4YDQK00TB00000000000001') THEN RAISE EXCEPTION 'cross-tenant read'; END IF;
  IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls)) THEN
    RAISE EXCEPTION 'unsafe runtime role';
  END IF;
  IF pg_has_role('twin_api','twin_owner','MEMBER') OR pg_has_role('twin_worker','twin_owner','MEMBER') THEN
    RAISE EXCEPTION 'runtime may inherit owner';
  END IF;
  BEGIN
    INSERT INTO twin.projects(id,organization_id,name,created_by)
      VALUES ('prj_01M4YDQK00TA00000000000099','org_01M4YDQK00TB00000000000000','Illegal','usr_01M4YDQK00TA00000000000001');
    RAISE EXCEPTION 'cross-tenant INSERT unexpectedly succeeded';
  EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  BEGIN
    INSERT INTO twin.models(id,organization_id,project_id,name,domain,created_by)
      VALUES ('mdl_01M4YDQK00TA00000000000099','org_01M4YDQK00TA00000000000000','prj_01M4YDQK00TB00000000000001','Illegal FK','software_delivery','usr_01M4YDQK00TA00000000000001');
    RAISE EXCEPTION 'cross-tenant parent FK unexpectedly succeeded';
  EXCEPTION WHEN foreign_key_violation THEN NULL; END;
END $$;
INSERT INTO twin.models(id,organization_id,project_id,name,domain,created_by)
 VALUES ('mdl_01M4YDQK00TA00000000000001','org_01M4YDQK00TA00000000000000','prj_01M4YDQK00TA00000000000001','Test Model','software_delivery','usr_01M4YDQK00TA00000000000001');
INSERT INTO twin.model_versions(id,organization_id,model_id,version,schema_version,ir,hash,created_by)
 VALUES ('mv_01M4YDQK00TA00000000000001','org_01M4YDQK00TA00000000000000','mdl_01M4YDQK00TA00000000000001',1,'0.1',
 '{"constraints":[],"domain":"software_delivery","entity_types":[{"id":"change","name":"Change"}],"flows":[{"from":"start","id":"start_work","routing":{"probability":1,"type":"probability"},"to":"work"},{"from":"work","id":"work_end","routing":{"probability":1,"type":"probability"},"to":"end"}],"metrics":[],"model_id":"mdl_01M4YDQK00TA00000000000001","name":"Model A v1","nodes":[{"arrival":{"distribution":{"type":"constant","value":10},"max_entities":1},"entity_type":"change","id":"start","type":"source"},{"id":"work","requires":[{"resource_id":"worker","units":1}],"service_time":{"distribution":{"type":"constant","value":1}},"type":"process"},{"id":"end","type":"sink"}],"resources":[{"capacity":1,"id":"worker","name":"Worker","queue_discipline":"fifo","type":"human"}],"schema_version":"0.1","time_unit":"minute","views":{"2d":{},"3d":{}}}',
 'sha256:432750f646ba93a763271505eaf1daa556ef60f2b8d7c97999529683c226120e','usr_01M4YDQK00TA00000000000001');
UPDATE twin.models SET latest_version_id='mv_01M4YDQK00TA00000000000001' WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='mdl_01M4YDQK00TA00000000000001';
-- Force deferred FK/manifest checks while still in the matching tenant context.
SET CONSTRAINTS ALL IMMEDIATE;
SET CONSTRAINTS ALL DEFERRED;
DO $$
BEGIN
  IF has_table_privilege('twin_api','twin.model_versions','UPDATE') THEN
    RAISE EXCEPTION 'API may update immutable version';
  END IF;
  IF has_table_privilege('twin_worker','twin.model_versions','INSERT') OR
     has_table_privilege('twin_worker','twin.scenarios','INSERT') THEN
    RAISE EXCEPTION 'worker may publish canonical effect';
  END IF;
END $$;
SET LOCAL ROLE twin_owner;
DO $$
BEGIN
  BEGIN
    UPDATE twin.model_versions SET ir=ir||'{"name":"tampered"}'::jsonb
      WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='mv_01M4YDQK00TA00000000000001';
    RAISE EXCEPTION 'immutable trigger missing';
  EXCEPTION WHEN SQLSTATE '55000' THEN NULL; END;
END $$;
SET LOCAL ROLE twin_api;
SELECT set_config('app.organization_id','',true);
DO $$
BEGIN
  IF EXISTS(SELECT 1 FROM twin.projects) THEN RAISE EXCEPTION 'no-context read should return no rows'; END IF;
END $$;
ROLLBACK;
-- Pool reuse, true runtime-login SET ROLE rejection, concurrent claim/approval,
-- object storage and API role tests still require the application integration suite.
